cat << 'EOF' > /app/generate_report.py
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO

# Set style
sns.set_theme(style="whitegrid")
plt.rcParams['font.family'] = 'sans-serif'

def get_base64_image(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# Load data
df = pd.read_csv('/app/benchmark/data.csv')
df['date'] = pd.to_datetime(df['date'])
df['year'] = df['date'].dt.year

# Calculate KPIs
avg_petrol = df['petrol_usd_liter'].mean()
corr_petrol = df['brent_crude_usd'].corr(df['petrol_usd_liter'])
corr_diesel = df['brent_crude_usd'].corr(df['diesel_usd_liter'])

# Subsidy Price Dampening Effect
subsidy_effect = df.groupby('subsidy_level')['petrol_usd_liter'].mean()
if 'High' in subsidy_effect and 'Low' in subsidy_effect:
    dampening_effect = ((subsidy_effect['Low'] - subsidy_effect['High']) / subsidy_effect['Low']) * 100
else:
    dampening_effect = 0

# Regional Price Spread (latest year)
latest_year = df['year'].max()
regional_prices_latest = df[df['year'] == latest_year].groupby('region')['petrol_usd_liter'].mean()
regional_spread = regional_prices_latest.max() - regional_prices_latest.min()

# Tax-to-Price Ratio by Income Level
tax_ratio = df.groupby('income_level')['tax_percentage'].mean()

# --- Section 1: Global Fuel Price Overview ---
# overall averages
overview_stats = df[['petrol_usd_liter', 'diesel_usd_liter', 'lpg_usd_liter']].mean()

# --- Section 2: Temporal Price Trends & Volatility ---
fig1, ax1 = plt.subplots(figsize=(10, 5))
monthly_prices = df.groupby(pd.Grouper(key='date', freq='M'))[['petrol_usd_liter', 'diesel_usd_liter', 'brent_crude_usd']].mean().reset_index()
ax1.plot(monthly_prices['date'], monthly_prices['petrol_usd_liter'], label='Petrol (USD/L)', color='#1f77b4')
ax1.plot(monthly_prices['date'], monthly_prices['diesel_usd_liter'], label='Diesel (USD/L)', color='#ff7f0e')
ax1.set_ylabel('Retail Price (USD/Liter)')
ax2 = ax1.twinx()
ax2.plot(monthly_prices['date'], monthly_prices['brent_crude_usd'], label='Brent Crude (USD/bbl)', color='#2ca02c', linestyle='--')
ax2.set_ylabel('Brent Crude (USD/bbl)')
fig1.legend(loc='upper left', bbox_to_anchor=(0.1, 0.9))
plt.title('Global Average Fuel Prices vs Brent Crude (2020-2026)')
img_temporal = get_base64_image(fig1)

# --- Section 3: Regional Price Disparities ---
fig2, ax = plt.subplots(figsize=(10, 5))
regional_yearly = df.groupby(['year', 'region'])['petrol_usd_liter'].mean().unstack()
regional_yearly.plot(ax=ax, marker='o')
plt.title('Regional Petrol Prices Over Time (USD/Liter)')
plt.ylabel('Petrol Price (USD/Liter)')
plt.legend(title='Region', bbox_to_anchor=(1.05, 1), loc='upper left')
img_regional = get_base64_image(fig2)

# --- Section 4: Impact of Subsidies and Taxation ---
fig3, axes = plt.subplots(1, 2, figsize=(12, 5))
sns.boxplot(data=df, x='subsidy_level', y='petrol_usd_liter', ax=axes[0], palette='Set2')
axes[0].set_title('Petrol Price by Subsidy Level')
axes[0].set_ylabel('Petrol (USD/Liter)')
axes[0].set_xlabel('Subsidy Level')

sns.scatterplot(data=df.sample(2000), x='brent_crude_usd', y='petrol_usd_liter', hue='subsidy_level', alpha=0.5, ax=axes[1], palette='Set2')
axes[1].set_title('Brent Crude vs Retail Petrol (Subsidized vs Not)')
axes[1].set_xlabel('Brent Crude (USD/bbl)')
axes[1].set_ylabel('Petrol (USD/Liter)')
img_subsidy = get_base64_image(fig3)

# --- Section 5: Fuel Affordability by Income Level ---
fig4, axes = plt.subplots(1, 2, figsize=(12, 5))
sns.barplot(data=df, x='income_level', y='petrol_usd_liter', ax=axes[0], palette='Pastel1', order=['Low', 'Middle', 'High'])
axes[0].set_title('Average Petrol Price by Income Level')
axes[0].set_ylabel('Petrol (USD/Liter)')

sns.barplot(data=df, x='income_level', y='tax_percentage', ax=axes[1], palette='Pastel1', order=['Low', 'Middle', 'High'])
axes[1].set_title('Average Tax Percentage by Income Level')
axes[1].set_ylabel('Tax Percentage (%)')
img_income = get_base64_image(fig4)

html_content = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Global Fuel Price Trends & Policy Impact Analysis (2020–2026)</title>
    <style>
        :root {{
            --primary: #2c3e50;
            --secondary: #34495e;
            --accent: #3498db;
            --bg: #f8f9fa;
            --card-bg: #ffffff;
            --text: #333333;
            --text-light: #666666;
            --border: #e2e8f0;
        }}
        body {{
            font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
            line-height: 1.6;
            color: var(--text);
            background-color: var(--bg);
            margin: 0;
            padding: 0;
        }}
        .container {{
            max-width: 1200px;
            margin: 0 auto;
            padding: 40px 20px;
        }}
        header {{
            text-align: center;
            margin-bottom: 50px;
            border-bottom: 2px solid var(--border);
            padding-bottom: 30px;
        }}
        h1 {{
            color: var(--primary);
            font-size: 2.5rem;
            margin-bottom: 10px;
        }}
        .subtitle {{
            color: var(--text-light);
            font-size: 1.2rem;
            max-width: 800px;
            margin: 0 auto;
        }}
        h2 {{
            color: var(--primary);
            border-bottom: 2px solid var(--accent);
            padding-bottom: 10px;
            margin-top: 40px;
        }}
        .kpi-container {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 40px;
        }}
        .kpi-card {{
            background: var(--card-bg);
            border-radius: 8px;
            padding: 20px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
            text-align: center;
            border-top: 4px solid var(--accent);
        }}
        .kpi-value {{
            font-size: 2rem;
            font-weight: bold;
            color: var(--primary);
            margin: 10px 0;
        }}
        .kpi-label {{
            font-size: 0.9rem;
            color: var(--text-light);
            text-transform: uppercase;
            letter-spacing: 1px;
        }}
        .kpi-desc {{
            font-size: 0.8rem;
            color: #7f8c8d;
            margin-top: 8px;
        }}
        .chart-container {{
            background: var(--card-bg);
            border-radius: 8px;
            padding: 20px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
            margin-bottom: 30px;
            text-align: center;
        }}
        .chart-container img {{
            max-width: 100%;
            height: auto;
        }}
        .findings-list {{
            background: var(--card-bg);
            border-radius: 8px;
            padding: 30px 40px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
        }}
        .findings-list li {{
            margin-bottom: 15px;
            font-size: 1.05rem;
        }}
        .findings-list li strong {{
            color: var(--primary);
        }}
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>Global Fuel Price Trends & Policy Impact Analysis</h1>
            <div class="subtitle">A comprehensive trend analysis of retail fuel prices across 84 countries (2020–2026), examining the interplay between Brent Crude benchmarks, taxation, subsidies, and regional economic conditions.</div>
        </header>

        <h2>Executive Dashboard (KPIs)</h2>
        <div class="kpi-container">
            <div class="kpi-card">
                <div class="kpi-label">Avg Petrol Price</div>
                <div class="kpi-value">${avg_petrol:.2f}</div>
                <div class="kpi-desc">USD/Liter across all regions</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-label">Brent-Retail Correlation</div>
                <div class="kpi-value">{corr_petrol:.2f}</div>
                <div class="kpi-desc">Pearson coeff. (Petrol vs Brent)</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-label">Subsidy Dampening</div>
                <div class="kpi-value">{dampening_effect:.1f}%</div>
                <div class="kpi-desc">Price reduction in High vs Low subsidy regimes</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-label">Regional Price Spread</div>
                <div class="kpi-value">${regional_spread:.2f}</div>
                <div class="kpi-desc">Max-Min regional avg spread (latest year)</div>
            </div>
        </div>

        <h2>Global Fuel Price Overview</h2>
        <p>Over the 2020–2026 period, retail fuel prices have shown significant volatility, largely driven by global crude oil market dynamics and local fiscal policies. The overall global average price for petrol was <strong>${overview_stats['petrol_usd_liter']:.2f}/liter</strong>, while diesel averaged <strong>${overview_stats['diesel_usd_liter']:.2f}/liter</strong> and LPG averaged <strong>${overview_stats['lpg_usd_liter']:.2f}/liter</strong>. These averages mask significant underlying disparities driven by national policies, economic statuses, and geographic locations.</p>

        <h2>Temporal Price Trends & Volatility</h2>
        <p>Retail fuel prices closely track the global benchmark, Brent Crude, with a strong correlation of <strong>{corr_petrol:.2f}</strong> for petrol and <strong>{corr_diesel:.2f}</strong> for diesel. The COVID-19 demand shock in early 2020 led to historic lows in crude prices, which subsequently reflected in lower retail costs. Conversely, the 2022 energy crisis saw Brent Crude prices spike significantly, driving retail prices to multi-year highs across most markets.</p>
        <div class="chart-container">
            <img src="data:image/png;base64,{img_temporal}" alt="Temporal Price Trends">
        </div>

        <h2>Regional Price Disparities</h2>
        <p>Geographic disparities in fuel pricing are substantial. In {latest_year}, the spread between the highest and lowest regional average petrol price reached <strong>${regional_spread:.2f}/liter</strong>. Regions with structural reliance on fuel imports or high consumption taxes consistently register higher retail prices, whereas regions comprising major oil producers often benefit from lower baseline costs.</p>
        <div class="chart-container">
            <img src="data:image/png;base64,{img_regional}" alt="Regional Price Disparities">
        </div>

        <h2>Impact of Subsidies and Taxation on Retail Prices</h2>
        <p>Government intervention plays a crucial role in buffering consumers from global volatility. High-subsidy countries effectively dampened retail prices, resulting in an average price reduction of <strong>{dampening_effect:.1f}%</strong> compared to low-subsidy countries. Furthermore, high-subsidy environments exhibit a flatter response to Brent Crude spikes, protecting consumers during the 2022 crisis at the cost of significant fiscal outlay.</p>
        <div class="chart-container">
            <img src="data:image/png;base64,{img_subsidy}" alt="Subsidy Impact">
        </div>

        <h2>Fuel Affordability by Income Level</h2>
        <p>National income classification strongly correlates with both retail fuel prices and taxation strategies. High-income nations generally impose heavier tax burdens (averaging <strong>{tax_ratio.get('High', 0):.1f}%</strong>), leading to higher nominal prices at the pump. In contrast, Low-income countries average a lower tax burden (<strong>{tax_ratio.get('Low', 0):.1f}%</strong>), reflecting policies aimed at keeping essential energy accessible, despite the fiscal strain it places on national budgets.</p>
        <div class="chart-container">
            <img src="data:image/png;base64,{img_income}" alt="Income Level Affordability">
        </div>

        <h2>Key Findings & Policy Implications</h2>
        <div class="findings-list">
            <ol>
                <li><strong>Volatility Transmission is High:</strong> With a {corr_petrol:.2f} correlation between Brent Crude and retail petrol, global shocks rapidly transmit to local consumers. Policymakers must maintain strategic reserves or financial buffers to manage sudden spikes.</li>
                <li><strong>Subsidies Effectively Dampen Shocks:</strong> High-subsidy regimes achieved a {dampening_effect:.1f}% price reduction, shielding populations during the 2022 crisis. However, the flat price response to crude spikes implies massive, unpredictable fiscal liabilities for governments.</li>
                <li><strong>Tax Calibration Drives Regional Inequality:</strong> High-income countries use fuel taxes as a reliable revenue stream, leading to higher baseline prices but encouraging fuel efficiency. Low- and middle-income countries should consider transitioning from blanket subsidies to targeted cash transfers to protect vulnerable populations without subsidizing wealthy consumers.</li>
                <li><strong>Persistent Regional Spread:</strong> A regional spread of ${regional_spread:.2f}/liter in the most recent year highlights that local fiscal policy often overrides global commodity pricing in determining the end-user cost.</li>
            </ol>
        </div>
    </div>
</body>
</html>
"""

with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:
    f.write(html_content)

print("Report generated successfully.")
